<!-- Hand-authored — NOT generated by prism, and prism will not overwrite it -->
<!-- (it only replaces files carrying its header). See the React wrapper for  -->
<!-- the reasoning: virtualization is the one case where the wrapper has to   -->
<!-- own the rows, because only Vue can create a Vue row. Rows come from the  -->
<!-- `row` scoped slot, which is the Vue-native way to say "render this item".-->
<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref, shallowRef, computed } from 'vue';
import '@arclux/arc-ui/virtual-list';

defineOptions({ name: 'VirtualList' });

const props = withDefaults(defineProps<{
  /** The full data array. Only the visible slice is rendered. */
  items: unknown[];
  /** Row height in pixels. Must match what actually renders. */
  itemHeight?: number;
  /** Rows rendered above and below the viewport, to cover fast scrolling. */
  overscan?: number;
}>(), {
  itemHeight: 40,
  overscan: 5,
});

const emit = defineEmits<{
  /** The visible range changed. `end` is exclusive. */
  'range-change': [range: { start: number; end: number }];
}>();

defineSlots<{
  row(props: { item: unknown; index: number }): unknown;
}>();

type ListElement = HTMLElement & {
  items?: unknown[];
  visibleRange?: { start: number; end: number };
};

const el = shallowRef<ListElement>();
const range = ref({ start: 0, end: 0 });

function onRangeChange(e: Event) {
  const { start, end } = (e as CustomEvent).detail;
  range.value = { start, end };
  emit('range-change', { start, end });
}

onMounted(() => {
  const node = el.value;
  if (!node) return;
  node.addEventListener('arc-range-change', onRangeChange);
  // The element may have measured before this ran, in which case its first
  // range event is already spent.
  if (node.visibleRange) range.value = { ...node.visibleRange };
});

onBeforeUnmount(() => {
  el.value?.removeEventListener('arc-range-change', onRangeChange);
});

const visible = computed(() => {
  const out: { item: unknown; index: number }[] = [];
  for (let i = range.value.start; i < Math.min(range.value.end, props.items.length); i++) {
    out.push({ item: props.items[i], index: i });
  }
  return out;
});
</script>

<template>
  <!-- Plain bindings, as in every other wrapper here: for a custom element Vue
       sets a binding as a DOM property when the element has one, so `items`
       arrives as an array rather than stringified. -->
  <arc-virtual-list
    ref="el"
    :items="props.items"
    :itemHeight="props.itemHeight"
    :overscan="props.overscan"
  >
    <div v-for="row in visible" :key="row.index" :slot="`item-${row.index}`">
      <slot name="row" :item="row.item" :index="row.index" />
    </div>
  </arc-virtual-list>
</template>
